import{j as e}from"./index-P0itqdt5.js";import{L as n}from"./LegalLayout-I8xWu3jj.js";import{u as r}from"./react-vendor-B6KbklQe.js";import"./supabase-BH9cnazT.js";import"./icons-C-YSG70s.js";import"./Footer-09Yl6MUp.js";const s=[{title:"Overview",content:['This Refund Policy describes the conditions under which SnapQuote ("we", "our", "us") may issue refunds for subscription payments. We encourage you to read this policy carefully before purchasing any plan.',"Our goal is to be fair, transparent, and consistent. We stand behind the quality of our Service, and this policy reflects that commitment."]},{title:"No Refund Policy",content:["All subscription payments made to SnapQuote are non-refundable once the subscription period has been activated. This applies to both monthly and annual billing cycles.","When you purchase a subscription, you immediately gain full access to the features included in your plan. Due to the immediate and digital nature of our Service, we are unable to offer refunds once access has been granted.","This policy applies to all plans — Starter, Growth, and Pro — regardless of whether the subscription was purchased on a monthly or annual basis."]},{title:"Free Trial",content:["New users receive a free trial that includes 10 complimentary quotes at no charge. No payment is required to activate or use the trial.","The free trial is designed to allow you to evaluate SnapQuote before committing to a paid subscription. We strongly encourage you to use the trial period to determine whether the Service meets your needs.","No refunds are applicable to trial usage, as no payment is collected during the trial."]},{title:"Exceptions — Technical Failures",content:["We may, at our sole discretion, consider refund requests in the event of a verified technical failure on our part that prevented you from accessing the Service for an extended, uninterrupted period.","To be eligible for an exception, the following conditions must be met:","(a) The service disruption must have been caused directly by a fault on SnapQuote's infrastructure — not by your device, internet connection, or third-party services.","(b) The disruption must have persisted for a continuous period of 72 hours or more, during which the core features of the Service were unavailable.","(c) The request must be submitted within 14 days of the disruption occurring, with clear documentation of the issue.","Partial refunds or account credits may be offered at our discretion in verified cases. We will not issue refunds for minor service interruptions, scheduled maintenance windows, or issues outside our control."]},{title:"Cancellations",content:["You may cancel your subscription at any time from your account settings. Upon cancellation, your plan will remain active until the end of the current billing period — no further charges will be made thereafter.","Cancellation does not entitle you to a refund for the current or any prior billing period. Access to paid features will cease at the end of the period for which payment has been made."]},{title:"Duplicate or Erroneous Charges",content:["If you believe you have been charged incorrectly — such as a duplicate transaction or an amount that does not match your selected plan — please contact us immediately at contact@snapquote.in.","We will investigate the matter promptly. Confirmed erroneous charges will be refunded in full within 7–10 business days via the original payment method."]},{title:"How to Request a Refund",content:["To submit a refund request, please contact our support team at contact@snapquote.in with the following details:","— Your registered email address","— The date of the transaction in question","— The Razorpay Payment ID (available in your email receipt)","— A clear description of the issue or reason for the request","We aim to respond to all refund requests within 3 business days."]},{title:"Contact Us",content:["If you have any questions about our Refund Policy, please reach out:","Email: contact@snapquote.in"]}];function m(){const a=r();return e.jsxs(n,{title:"Refund Policy",lastUpdated:"April 1, 2026",onBack:()=>a(-1),children:[e.jsxs("div",{className:"mb-8 p-4 bg-amber-50 border border-amber-200 rounded-lg",children:[e.jsx("p",{className:"text-sm font-semibold text-amber-800 mb-1",children:"Important Notice"}),e.jsx("p",{className:"text-sm text-amber-700 leading-relaxed",children:"All subscriptions are non-refundable once activated. Exceptions are only considered in the event of a verified technical failure on our part. Please read the full policy below before purchasing."})]}),s.map(t=>e.jsxs("section",{className:"mb-10",children:[e.jsx("h2",{className:"text-base font-semibold text-slate-900 mb-3",children:t.title}),e.jsx("div",{className:"space-y-3",children:t.content.map((o,i)=>e.jsx("p",{className:"text-sm text-slate-600 leading-relaxed",children:o},i))})]},t.title))]})}export{m as RefundPolicy};
